import { isNoColor } from './theme.js';

const BOLD = '\x1b[1m';
const DIM = '\x1b[2m';
const CYAN = '\x1b[36m';
const RESET = '\x1b[0m';
const CODE_BLOCK_RE = /```[\s\S]*?```/g;
const INLINE_CODE_RE = /`([^`]+)`/g;
const BOLD_RE = /\*\*([^*]+)\*\*/g;
const ITALIC_RE = /\*([^*]+)\*/g;
const HEADER_RE = /^(#{1,6})\s+(.+)$/gm;
const BULLET_RE = /^(\s*)[-*]\s+(.+)$/gm;
const BLOCKQUOTE_RE = /^>\s?(.+)$/gm;

export function markdownToAnsi(text: string): string {
  if (text === '') return '';

  const noColor = isNoColor();

  // Process code blocks first (protect from inner parsing)
  const codeBlockPlaceholders: string[] = [];
  let result = text.replace(CODE_BLOCK_RE, (match) => {
    const inner = match.replace(/^```\w*\n?/, '').replace(/\n?```$/, '');
    const idx = codeBlockPlaceholders.length;
    if (noColor) {
      codeBlockPlaceholders.push(inner);
    } else {
      codeBlockPlaceholders.push(`${CYAN}${inner}${RESET}`);
    }
    return `\x00CB${idx}\x00`;
  });

  // Process inline elements
  // Inline code
  result = result.replace(INLINE_CODE_RE, (_match, code: string) => {
    if (noColor) return code;
    return `${CYAN}${code}${RESET}`;
  });

  // Bold
  result = result.replace(BOLD_RE, (_match, content: string) => {
    if (noColor) return content;
    return `${BOLD}${content}${RESET}`;
  });

  // Italic (use dim since italic not supported)
  result = result.replace(ITALIC_RE, (_match, content: string) => {
    if (noColor) return content;
    return `${DIM}${content}${RESET}`;
  });

  // Headers
  result = result.replace(HEADER_RE, (_match, _hashes: string, content: string) => {
    if (noColor) return content;
    return `${BOLD}${content}${RESET}`;
  });

  // Bullets
  result = result.replace(BULLET_RE, (_match, indent: string, content: string) => {
    return `${indent}• ${content}`;
  });

  // Blockquotes
  result = result.replace(BLOCKQUOTE_RE, (_match, content: string) => {
    if (noColor) return `│ ${content}`;
    return `${DIM}│ ${content}${RESET}`;
  });

  // Restore code blocks
  result = result.replace(/\x00CB(\d+)\x00/g, (_match, idx: string) => {
    return codeBlockPlaceholders[Number(idx)] ?? '';
  });

  return result;
}
```

